{"file_path":"src/nodes.js","content":"/**
 * The document model. Every node carries a tag so that a table, an array of
 * tables and a plain array stay apart from one another after parsing.
 */

/** A parse failure, carrying the line it happened on and its reason. */
export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

/** A table. `explicit` records that a `[name]` header already named it. */
export function makeTable(explicit = false) {
  return { t: 'table', map: new Map(), explicit }
}

/** An array of tables, grown by `[[name]]` headers. */
export function makeArrayTable() {
  return { t: 'atable', items: [] }
}

/** An array written as a value. */
export function makeArray(items) {
  return { t: 'array', items }
}

/** A scalar of one of the four scalar types. */
export function makeScalar(type, value) {
  return { t: type, v: value }
}

/** The path of a child key below `base`. */
export function joinKey(base, key) {
  return base === '' ? key : `${base}.${key}`
}

/** The path of the element at `index` of the array at `base`. */
export function joinIndex(base, index) {
  return `${base}[${index}]`
}
"}

