{"file_path":"src/parse.js","content":"/**
 * The parser. It reads the configuration document one line at a time and
 * builds the document model, throwing a ParseError at the first failure.
 */

import {
  ParseError,
  makeTable,
  makeArrayTable,
  makeArray,
  makeScalar,
  joinKey,
  joinIndex,
} from './nodes.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/

/** The characters that end a bare value word. */
function endsWord(c) {
  return c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}' || c === ';'
}

/** Parses one document, returning its root table. */
export function parse(text) {
  const lines = splitLines(text)
  const root = makeTable(true)
  let current = root
  let currentPath = ''

  for (let index = 0; index < lines.length; index += 1) {
    const line = new Line(lines[index], index + 1)
    line.skipBlank()
    if (line.done()) continue
    if (line.peek() === '[') {
      const header = line.parseHeader()
      const target = applyHeader(root, header, line)
      current = target.table
      currentPath = target.path
    } else {
      const names = line.parseDottedName()
      line.skipSpace()
      if (line.peek() !== '=') line.fail('expected key = value')
      line.next()
      const value = line.parseValue(currentPath)
      line.finishValue()
      assign(current, currentPath, names, value, line)
    }
  }
  return root
}

/** Splits the document, dropping the empty tail a trailing newline leaves. */
function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Walks `names` from `table`, creating tables, and stores the value. */
function assign(table, basePath, names, value, line) {
  let node = table
  let path = basePath
  for (let i = 0; i < names.length - 1; i += 1) {
    path = joinKey(path, names[i])
    let next = node.map.get(names[i])
    if (next === undefined) {
      next = makeTable(false)
      node.map.set(names[i], next)
    }
    if (next.t === 'table') {
      node = next
    } else if (next.t === 'atable' && next.items.length > 0) {
      path = joinIndex(path, next.items.length - 1)
      node = next.items[next.items.length - 1]
    } else {
      line.fail(`${path} is not a table`)
    }
  }
  const last = names[names.length - 1]
  path = joinKey(path, last)
  if (node.map.has(last)) line.fail(`key ${path} is defined twice`)
  node.map.set(last, value)
}

/** Walks the names of a header, returning the table the last one sits in. */
function walkHeader(root, names, line) {
  let node = root
  let path = ''
  for (let i = 0; i < names.length - 1; i += 1) {
    path = joinKey(path, names[i])
    let next = node.map.get(names[i])
    if (next === undefined) {
      next = makeTable(false)
      node.map.set(names[i], next)
    }
    if (next.t === 'table') {
      node = next
    } else if (next.t === 'atable' && next.items.length > 0) {
      path = joinIndex(path, next.items.length - 1)
      node = next.items[next.items.length - 1]
    } else {
      line.fail(`${path} is not a table`)
    }
  }
  return { node, path }
}

/** Applies a header, returning the table it makes current and its path. */
function applyHeader(root, header, line) {
  const { names, array } = header
  const { node, path } = walkHeader(root, names, line)
  const last = names[names.length - 1]
  const full = joinKey(path, last)
  const held = node.map.get(last)
  if (array) {
    let holder = held
    if (holder === undefined) {
      holder = makeArrayTable()
      node.map.set(last, holder)
    }
    if (holder.t !== 'atable') line.fail(`${full} is not an array of tables`)
    const fresh = makeTable(true)
    holder.items.push(fresh)
    return { table: fresh, path: joinIndex(full, holder.items.length - 1) }
  }
  if (held === undefined) {
    const fresh = makeTable(true)
    node.map.set(last, fresh)
    return { table: fresh, path: full }
  }
  if (held.t !== 'table') line.fail(`${full} is not a table`)
  if (held.explicit) line.fail(`table ${full} is defined twice`)
  held.explicit = true
  return { table: held, path: full }
}

/** One line of the document, with a cursor over it. */
class Line {
  constructor(text, number) {
    this.s = text
    this.i = 0
    this.n = number
  }

  fail(reason) {
    throw new ParseError(this.n, reason)
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : ''
  }

  next() {
    this.i += 1
  }

  skipSpace() {
    while (this.i < this.s.length && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) {
      this.i += 1
    }
  }

  /** True once the rest of the line is empty or a comment. */
  done() {
    const c = this.peek()
    return c === '' || c === '#' || c === ';'
  }

  /** Skips to the first character that carries meaning on this line. */
  skipBlank() {
    this.skipSpace()
  }

  /** Requires that only spaces, tabs and a comment follow a value. */
  finishValue() {
    this.skipSpace()
    if (!this.done()) this.fail('trailing text after a value')
  }

  /** Reads a bare word or a quoted string. */
  parseName() {
    const c = this.peek()
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    if (c !== '' && NAME_CHAR.test(c)) {
      const start = this.i
      while (this.i < this.s.length && NAME_CHAR.test(this.s[this.i])) this.i += 1
      return this.s.slice(start, this.i)
    }
    return this.fail('expected a name')
  }

  /** Reads names joined by dots, with spaces and tabs around each dot. */
  parseDottedName() {
    const names = [this.parseName()]
    for (;;) {
      const mark = this.i
      this.skipSpace()
      if (this.peek() !== '.') {
        this.i = mark
        return names
      }
      this.next()
      this.skipSpace()
      names.push(this.parseName())
    }
  }

  parseBasicString() {
    this.next()
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i += 1
        return out
      }
      if (c === '\\') {
        this.i += 1
        if (this.i >= this.s.length) this.fail('unterminated string')
        const e = this.s[this.i]
        this.i += 1
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const hex = this.s.slice(this.i, this.i + 4)
          if (hex.length < 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) this.fail('invalid escape \\u')
          this.i += 4
          out += String.fromCharCode(parseInt(hex, 16))
        } else {
          this.fail(`invalid escape \\${e}`)
        }
        continue
      }
      out += c
      this.i += 1
    }
  }

  parseLiteralString() {
    this.next()
    const start = this.i
    while (this.i < this.s.length && this.s[this.i] !== "'") this.i += 1
    if (this.i >= this.s.length) this.fail('unterminated string')
    const out = this.s.slice(start, this.i)
    this.i += 1
    return out
  }

  /** Reads a table header, `[name]` or `[[name]]`. */
  parseHeader() {
    this.next()
    let array = false
    if (this.peek() === '[') {
      array = true
      this.next()
    }
    this.skipSpace()
    if (this.done()) this.fail('expected a name')
    const names = this.parseDottedName()
    this.skipSpace()
    if (this.peek() !== ']') this.fail('unterminated table header')
    this.next()
    if (array) {
      if (this.peek() !== ']') this.fail('unterminated table header')
      this.next()
    }
    this.skipSpace()
    if (!this.done()) this.fail('trailing text after a table header')
    return { names, array }
  }

  /** Reads one value. `path` names the value, for messages from inside it. */
  parseValue(path) {
    this.skipSpace()
    if (this.done()) this.fail('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return makeScalar('string', this.parseBasicString())
    if (c === "'") return makeScalar('string', this.parseLiteralString())
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    return this.parseWord()
  }

  /** Reads a bare word and decides which kind of value it spells. */
  parseWord() {
    const start = this.i
    while (this.i < this.s.length && !endsWord(this.s[this.i])) this.i += 1
    const word = this.s.slice(start, this.i)
    if (word === 'true') return makeScalar('boolean', true)
    if (word === 'false') return makeScalar('boolean', false)
    if (INTEGER.test(word)) return makeScalar('integer', Number(word.replace(/_/g, '')))
    if (FLOAT.test(word)) return makeScalar('float', Number(word.replace(/_/g, '')))
    return this.fail(`invalid value ${word}`)
  }

  parseArray(path) {
    this.next()
    const items = []
    for (;;) {
      this.skipSpace()
      if (this.done()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.next()
        return makeArray(items)
      }
      items.push(this.parseValue(joinIndex(path, items.length)))
      this.skipSpace()
      if (this.done()) this.fail('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.next()
        continue
      }
      if (c === ']') {
        this.next()
        return makeArray(items)
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.next()
    const table = makeTable(false)
    this.skipSpace()
    if (this.peek() === '}') {
      this.next()
      return table
    }
    for (;;) {
      this.skipSpace()
      if (this.done()) this.fail('unterminated inline table')
      const names = this.parseDottedName()
      this.skipSpace()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.next()
      const value = this.parseValue(pathOfPair(path, names))
      assign(table, path, names, value, this)
      this.skipSpace()
      if (this.done()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.next()
        continue
      }
      if (c === '}') {
        this.next()
        return table
      }
      this.fail('unterminated inline table')
    }
  }
}

/** The path a pair of an inline table writes to. */
function pathOfPair(path, names) {
  return names.reduce((acc, name) => joinKey(acc, name), path)
}
"}

