    if (this.peek() !== ']') this.fail('unterminated table header')
    this.next()
    if (array) {
      if (this.peek() !== ']') this.fail('unterminated table header')
      this.next()
    }
    this.skipSpace()
    if (!this.done()) this.fail('trailing text after a table header')
    return { names, array }
  }

  /** Reads one value. `path` names the value, for messages from inside it. */
  parseValue(path) {
    this.skipSpace()
    if (this.done()) this.fail('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return makeScalar('string', this.parseBasicString())
    if (c === "'") return makeScalar('string', this.parseLiteralString())
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    return this.parseWord()
  }

  /** Reads a bare word and decides which kind of value it spells. */
  parseWord() {
    const start = this.i
    while (this.i < this.s.length && !endsWord(this.s[this.i])) this.i += 1
    const word = this.s.slice(start, this.i)
    if (word === 'true') return makeScalar('boolean', true)
    if (word === 'false') return makeScalar('boolean', false)
    if (INTEGER.test(word)) return makeScalar('integer', Number(word.replace(/_/g, '')))
    if (FLOAT.test(word)) return makeScalar('float', Number(word.replace(/_/g, '')))
    return this.fail(`invalid value ${word}`)
  }

  parseArray(path) {
    this.next()
    const items = []
    for (;;) {
      this.skipSpace()
      if (this.done()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.next()
        return makeArray(items)
      }
      items.push(this.parseValue(joinIndex(path, items.length)))
      this.skipSpace()
      if (this.done()) this.fail('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.next()
        continue
      }
      if (c === ']') {
        this.next()
        return makeArray(items)
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.next()
    const table = makeTable(false)
    this.skipSpace()
    if (this.peek() === '}') {
      this.next()
      return table
    }
    for (;;) {
      this.skipSpace()
      if (this.done()) this.fail('unterminated inline table')
      const names = this.parseDottedName()
      this.skipSpace()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.next()
      const value = this.parseValue(pathOfPair(path, names))
      assign(table, path, names, value, this)
      this.skipSpace()
      if (this.done()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.next()
        continue
      }
      if (c === '}') {
        this.next()
        return table
      }
      this.fail('unterminated inline table')
    }
  }
}

/** The path a pair of an inline table writes to. */
function pathOfPair(path, names) {
  return names.reduce((acc, name) => joinKey(acc, name), path)
}
"}

