{"file_path":"src/render.js","content":"/**
 * The two ways of printing a parsed document: canonical JSON, and one line per
 * node giving its path and its type.
 */

/** Compares two strings by code point, ascending. */
export function compareKeys(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (left.length === right.length) return 0
  return left.length < right.length ? -1 : 1
}

/** The keys of a table in ascending order. */
function sortedKeys(node) {
  return Array.from(node.map.keys()).sort(compareKeys)
}

/** The type name a node reports. */
function typeOf(node) {
  if (node.t === 'atable') return 'array'
  return node.t
}

/** Turns a node into the plain value JSON.stringify should print. */
function plain(node) {
  if (node.t === 'table') {
    const out = {}
    for (const key of sortedKeys(node)) out[key] = plain(node.map.get(key))
    return out
  }
  if (node.t === 'array' || node.t === 'atable') return node.items.map(plain)
  return node.v
}

/** Prints the document as JSON indented by two spaces. */
export function toJson(root) {
  return `${JSON.stringify(plain(root), null, 2)}\n`
}

/** Prints one line per node below the root, depth first. */
export function toKeys(root) {
  const out = []
  walk(root, '', out)
  return out.map((line) => `${line}\n`).join('')
}

function walk(node, path, out) {
  if (node.t === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.map.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${typeOf(child)}`)
      walk(child, childPath, out)
    }
    return
  }
  if (node.t === 'array' || node.t === 'atable') {
    node.items.forEach((child, index) => {
      const childPath = `${path}[${index}]`
      out.push(`${childPath} ${typeOf(child)}`)
      walk(child, childPath, out)
    })
  }
}
"}

