{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { parse } from './parse.js'
import { ParseError } from './nodes.js'
import { toJson, toKeys } from './render.js'

/** Reads all of standard input, treating a closed input as empty. */
function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : ''
  if (mode !== 'json' && mode !== 'keys') {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  let out
  try {
    const root = parse(readInput())
    out = mode === 'json' ? toJson(root) : toKeys(root)
  } catch (error) {
    if (!(error instanceof ParseError)) throw error
    process.stderr.write(`error: line ${error.line}: ${error.reason}\n`)
    process.exit(2)
  }
  process.stdout.write(out)
}

main(process.argv.slice(2))
"}

